function [good] = gnss_usable(ok, r)
%GNSS_USABLE  Whether a GNSS fix may be taken: the receiver's flag, and the fix outside 0.9 R_E.
%   ok: bool (passed true or false)
%   r: real[1][3] (passed a plain number)
%   returns good: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    good = false;
    good = (ok && (sqrt(r(1)*r(1) + r(2)*r(2) + r(3)*r(3)) > (0.9 * 6378137)));
end
